#[cfg(test)]mod closed_constant_admission_controls{
 use super::*;
 fn fixture()->(IdTable<ExprId,Expr>,IdTable<LevelId,Level>,Environment){let mut e=IdTable::default();let mut l=IdTable::default();l.insert(LevelId(0),Level::Zero).unwrap();for(id,x)in[(0,Expr::Sort(LevelId(0))),(1,Expr::Const{name:NameId(1),levels:vec![]}),(2,Expr::Pi{domain:ExprId(1),body:ExprId(1)}),(3,Expr::Const{name:NameId(2),levels:vec![]}),(4,Expr::Const{name:NameId(3),levels:vec![]}),(5,Expr::BVar(0)),(6,Expr::BVar(1)),(7,Expr::App{fun:ExprId(6),arg:ExprId(5)}),(8,Expr::Const{name:NameId(4),levels:vec![]}),(9,Expr::Pi{domain:ExprId(1),body:ExprId(2)}),(10,Expr::Const{name:NameId(5),levels:vec![]})]{e.insert(ExprId(id),x).unwrap();}let env=Environment::empty().extend(NameId(1),crate::environment::ConstantDecl::axiom(vec![],ExprId(0))).unwrap().extend(NameId(2),crate::environment::ConstantDecl::axiom(vec![],ExprId(2))).unwrap().extend(NameId(3),crate::environment::ConstantDecl::axiom(vec![],ExprId(1))).unwrap().extend(NameId(4),crate::environment::ConstantDecl::axiom(vec![],ExprId(0))).unwrap().extend(NameId(5),crate::environment::ConstantDecl::axiom(vec![],ExprId(9))).unwrap();(e,l,env)}
 fn source(c:&TypeChecker<'_>,f:u64,a:u64)->Closure{c.closure(ExprId(7),EnvFrame::empty().extend(c.closure(ExprId(f),EnvFrame::empty())).extend(c.closure(ExprId(a),EnvFrame::empty())))}
 #[test]fn admitted_fact_was_established_in_empty_context(){let _flags=crate::run_flags::enter();let(e,l,env)=fixture();let c=TypeChecker::new(&e,&l,&env);let t=source(&c,3,4);let g=[TypeValue::Term(c.closure(ExprId(1),EnvFrame::empty()))];assert!(c.infer_exact_closure_in_context(&t,&g,&mut 4096,0).is_some());let table=c.exact_typing_memo.borrow();let facts=table.slots.iter().flatten().filter(|f|f.key.source.0==t.expr&&f.key.source.1==t.env.id()).collect::<Vec<_>>();assert_eq!(facts.len(),1);assert!(facts[0].closed_constant_scope);assert!(facts[0].context.is_empty());}
 #[test]fn closed_wrong_argument_is_not_a_typing_certificate(){let _flags=crate::run_flags::enter();let(e,l,env)=fixture();let c=TypeChecker::new(&e,&l,&env);let t=source(&c,3,8);let g=[TypeValue::Term(c.closure(ExprId(1),EnvFrame::empty()))];assert!(c.infer_exact_closure_in_context(&t,&g,&mut 4096,0).is_none());assert!(c.exact_typing_memo.borrow().slots.iter().flatten().all(|f|!f.closed_constant_scope));}
 #[test]fn nonconstant_term_type_keeps_original_scope(){let _flags=crate::run_flags::enter();let(e,l,env)=fixture();let c=TypeChecker::new(&e,&l,&env);let t=source(&c,10,4);let g=[TypeValue::Term(c.closure(ExprId(1),EnvFrame::empty()))];let first=c.infer_exact_closure_in_context(&t,&g,&mut 4096,0);assert!(matches!(first,Some(TypeValue::Term(_))));assert!(c.infer_exact_closure_in_context(&t,&[],&mut 1,0).is_none());let table=c.exact_typing_memo.borrow();let f=table.slots.iter().flatten().find(|f|f.key.source.0==t.expr&&f.key.source.1==t.env.id()).unwrap();assert!(!f.closed_constant_scope);assert_eq!(f.context.len(),1);}
 #[test]fn exhausted_admission_and_changed_actual_universe_map_never_reuse(){let _flags=crate::run_flags::enter();let(e,l,env)=fixture();let c=TypeChecker::new(&e,&l,&env);let t=source(&c,3,4);let g=[TypeValue::Term(c.closure(ExprId(1),EnvFrame::empty()))];assert!(c.infer_exact_closure_in_context(&t,&g,&mut 2,0).is_none());assert!(c.exact_typing_memo.borrow().slots.iter().flatten().all(|f|!f.closed_constant_scope));assert!(c.infer_exact_closure_in_context(&t,&g,&mut 4096,0).is_some());let changed=Closure::with_levels(t.expr,t.env.clone(),LevelSubstitution::new(vec![(NameId(99),LevelTerm::Zero)]));assert!(c.infer_exact_closure_in_context(&changed,&[],&mut 1,0).is_none());}
}
#[cfg(test)]mod captured_used_universe_controls{use super::*;
 #[test]fn actual_used_captured_universes_are_instantiated_before_closed_admission(){let _flags=crate::run_flags::enter();let mut e=IdTable::default();let mut l=IdTable::default();l.insert(LevelId(0),Level::Zero).unwrap();l.insert(LevelId(1),Level::Param(NameId(7))).unwrap();for(id,x)in[(0,Expr::Sort(LevelId(1))),(1,Expr::Const{name:NameId(1),levels:vec![LevelId(1)]}),(2,Expr::Pi{domain:ExprId(1),body:ExprId(1)}),(3,Expr::Const{name:NameId(2),levels:vec![LevelId(1)]}),(4,Expr::Const{name:NameId(3),levels:vec![LevelId(1)]}),(5,Expr::BVar(0)),(6,Expr::BVar(1)),(7,Expr::App{fun:ExprId(6),arg:ExprId(5)}),(9,Expr::Sort(LevelId(0))) ]{e.insert(ExprId(id),x).unwrap();}let env=Environment::empty().extend(NameId(1),crate::environment::ConstantDecl::axiom(vec![NameId(7)],ExprId(0))).unwrap().extend(NameId(2),crate::environment::ConstantDecl::axiom(vec![NameId(7)],ExprId(2))).unwrap().extend(NameId(3),crate::environment::ConstantDecl::axiom(vec![NameId(7)],ExprId(1))).unwrap();let c=TypeChecker::new(&e,&l,&env);let g=[TypeValue::Term(c.closure(ExprId(9),EnvFrame::empty()))];let source=|f:LevelTerm,a:LevelTerm|c.closure(ExprId(7),EnvFrame::empty().extend(Closure::with_levels(ExprId(3),EnvFrame::empty(),LevelSubstitution::new(vec![(NameId(7),f)]))).extend(Closure::with_levels(ExprId(4),EnvFrame::empty(),LevelSubstitution::new(vec![(NameId(7),a)]))));for u in[LevelTerm::Zero,succ(LevelTerm::Zero)]{let t=source(u.clone(),u.clone());let first=c.infer_exact_closure_in_context(&t,&g,&mut 8192,0);let Some(TypeValue::Term(ty))=first.clone()else{panic!("matched used universes must typecheck: {first:?}")};assert_eq!(c.infer_exact_closure_in_context(&t,&[],&mut 1,0),first);let exposed=c.machine().expose(ty,Transparency::Opaque,256);assert!(matches!(exposed.proven_value(),Some(Value::Neutral(Neutral{head:NeutralHead::Const{name:NameId(1),levels},spine}))if levels==&vec![u]&&spine.is_empty()));}let wrong=source(LevelTerm::Zero,succ(LevelTerm::Zero));assert!(c.infer_exact_closure_in_context(&wrong,&g,&mut 8192,0).is_none(),"different used captured universes must not inherit a closed warrant");}
}
